{"content":"from log_parser import parse_line, status_counts


def test_normal_line():
    e = parse_line('203.0.113.9 - alice [10/Oct/2026:13:55:36 +0000] "GET /login HTTP/1.1" 200 5120')
    assert e["ip"] == "203.0.113.9" and e["user"] == "alice"
    assert e["status"] == 200 and e["size"] == 5120 and e["path"] == "/login"


def test_anonymous_user():
    e = parse_line('203.0.113.9 - - [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1" 200 512')
    assert e["user"] is None


def test_no_body_size():
    e = parse_line('126.174.81.54 - alice [10/Oct/2026:19:05:07 +0000] "GET /static/app.12852.js HTTP/1.1" 200 -')
    assert e["size"] == 0


def test_ipv6_address():
    e = parse_line('2001:db8:1f::a3 - svc-backup [12/Oct/2026:12:47:32 +0000] "GET /login HTTP/1.1" 200 141170')
    assert e["ip"] == "2001:db8:1f::a3"
    assert e["user"] == "svc-backup"


def test_username_special_chars():
    for name in ("j.doe", "svc-backup", "carol_92"):
        line = f'203.0.113.9 - {name} [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1" 200 512'
        e = parse_line(line)
        assert e["user"] == name


def test_invalid_lines():
    assert parse_line("") is None
    assert parse_line("GARBAGE ### line") is None
    assert parse_line('10.0.0.1 - - [10/Oct/2026:13:55:36 +0000] "GET /api/ord') is None


def test_status_counts():
    counts = status_counts("data/access.log")
    assert isinstance(counts, dict)
    assert 200 in counts
    assert counts[200] > 0
